SELECT CASE WHEN monthly_fee >= 184 THEN 'high' WHEN monthly_fee >= 87 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, COUNT(DISTINCT monthly_fee) AS unique_customers, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM subscriptions WHERE MONTH(end_date) IN (2, 5, 7) AND (status = 'CANCELLED' OR start_date > '2025-05-01') GROUP BY CASE WHEN monthly_fee >= 184 THEN 'high' WHEN monthly_fee >= 87 THEN 'mid' ELSE 'low' END
